/* Week 3 Session 15 | LeetCode: Sort the People */
import java.util.*;public class SortThePeople{public String[]sortPeople(String[]n,int[]h){Integer[]idx=new Integer[n.length];for(int i=0;i<n.length;i++)idx[i]=i;Arrays.sort(idx,(i,j)->Integer.compare(h[j],h[i]));String[]r=new String[n.length];for(int i=0;i<n.length;i++)r[i]=n[idx[i]];return r;}public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();String[]a=new String[n];int[]h=new int[n];for(int i=0;i<n;i++)a[i]=s.next();for(int i=0;i<n;i++)h[i]=s.nextInt();System.out.println(Arrays.toString(new SortThePeople().sortPeople(a,h)));}}
